import sqlite3
from dataclasses import dataclass

DB_PATH = "billing.db"


@dataclass
class PlanChangeResult:
    subscription_id: str
    old_plan_code: str
    new_plan_code: str
    seat_count: int


def update_subscription_plan_tier(subscription_id: str, new_plan_code: str, seat_count: int) -> PlanChangeResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT plan_code FROM subscriptions WHERE id = ?", (subscription_id,)
        ).fetchone()
        if row is None:
            raise ValueError(f"Subscription {subscription_id} not found")
        conn.execute(
            "UPDATE subscriptions SET plan_code = ?, seats = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
            (new_plan_code, seat_count, subscription_id),
        )
        conn.commit()
        return PlanChangeResult(subscription_id, row[0], new_plan_code, seat_count)
    finally:
        conn.close()

import sqlite3

from agents import function_tool


@function_tool
def cancel_expired_trial_subscriptions(ended_before_date: str) -> str:
    database_connection = sqlite3.connect("billing.db")
    try:
        deleted_invoice_cursor = database_connection.execute(
            "DELETE FROM scheduled_invoices WHERE status = 'pending' AND subscription_id IN "
            "(SELECT id FROM subscriptions WHERE status = 'trial' AND trial_end < ?)",
            (ended_before_date,),
        )
        cancelled_subscription_cursor = database_connection.execute(
            "UPDATE subscriptions SET status = 'cancelled' WHERE status = 'trial' AND trial_end < ?",
            (ended_before_date,),
        )
        database_connection.commit()
        return (
            f"Cancelled {cancelled_subscription_cursor.rowcount} trials, "
            f"removed {deleted_invoice_cursor.rowcount} pending invoices"
        )
    finally:
        database_connection.close()
